        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Das Religiöse stehet der weiblichen Bescheidenheit sehr wohl; es gibt der Schönheit ein gewisses edles, gesetztes und schmachtendes Ansehen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Die beste Lunge erschöpft sich, auch sogar eine weibliche.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Laß dich den Teufel bey Einem Haare fassen; und du bist sein auf ewig?", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Noch einen Schritt vom Ziele, oder noch gar nicht ausgelaufen seyn, ist im Grunde eines.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "daß man den Künstler dann erst recht lobt, wenn man über sein Werk sein Lob vergißt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Perlen bedeuten Thränen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Still mit dem Aber! Die Aber kosten Überlegung.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Thu, was du nicht lassen kannst!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Vor allen Dingen, eine Kleinigkeit als eine Kleinigkeit ansehen!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was Gewalt heißt, ist nichts: Verführung ist die wahre Gewalt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was macht die Kunst? - Prinz, die Kunst geht nach Brodt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Wer über gewisse Dinge den Verstand nicht verlieret, der hat keinen zu verlieren.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Denn nichts ist groß, was nicht wahr ist.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Name Mutter ist süß; aber Frau Mutter ist wahrer Honig mit Zitronensaft.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Die Komödie will durch Lachen bessern, aber nicht eben durch Verlachen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Die Poesie geht mehr auf das Allgemeine und die Geschichte auf das Besondere.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "In der Natur ist alles mit allem verbunden, alles durchkreuzt sich, alles wechselt mit allem, alles verändert sich eines in das andere.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Nicht jeder Kunstrichter ist ein Genie, aber jedes Genie ist ein geborener Kunstrichter.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Nicht jeder, der den Pinsel in die Hand nimmt und Farben verquistet, ist ein Maler.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "So wie es selten Komplimente gibt ohne alle Lügen, so findet sich auch selten Grobheiten ohne alle Wahrheit.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Das Herz redet uns gewaltig gern nach dem Maule. Wenn das Maul eben so geneigt wäre, nach dem Herzen zu reden, so wäre die Mode längst aufgekommen, die Mäuler unter'm Schlosse zu tragen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Freue dich mit mir! Es ist so traurig, sich allein zu freuen!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Ich brauche keine Gnade, ich will Gerechtigkeit.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Man muss nicht reicher scheinen wollen, als man ist.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was kann der Schöpfer lieber sehen als ein fröhliches Geschöpf!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es wäre wenig in der Welt unternommen worden, wenn man nur immer auf den Ausgang gesehen hätte.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Aberglaube des schlimmsten ist, den seinen für den erträglicheren zu halten.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Wunder höchstes ist, dass uns die wahren, echten Wunder so alltäglich werden können, werden sollen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Erröten macht die Hässlichen so schön.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es ist Arznei, nicht Gift, was ich dir reiche.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es sind nicht alle frei, die ihrer Ketten spotten.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Ich fürchte, grad unter Menschen möchtest du, ein Mensch zu sein verlernen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Jeder liebt sich selber nur am meisten.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Kein Mensch muss müssen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Macht denn nur das Blut den Vater?", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Nicht die Kinder bloß speist man mit Märchen ab.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was hätt' ein Weiberkopf erdacht, das er nicht zu beschönen wüsste.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Wille und nicht die Gabe macht den Geber.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es eifre jeder seiner unbestochnen von Vorurteilen freien Liebe nach!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Damit er einst was kann von seinen Eltern erben, so lassen sie ihn jetzt vor Hunger weislich sterben.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es hat der Schuster Franz zum Dichter sich entzückt. // Was er als Schuster tat, das tut er noch: er flickt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Wer wird nicht einen Klopstock loben? // Doch wird ihn jeder lesen? Nein! // Wir wollen weniger erhoben // und fleißiger gelesen sein.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Aberglaube traut den Sinnen bald zu viel, bald zu wenig.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Begriff ist der Mann; das sinnliche Bild des Begriffes ist das Weib; und die Worte sind die Kinder, welche beyde hervorbringen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der mitleidigste Mensch ist der beste Mensch.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Der Rezensent braucht nicht besser machen zu können, was er tadelt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Die beste Anbetung, Prinz, ist dankende Freude.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Die Menge auf etwas aufmerksam machen heißt: dem gesunden Menschenverstand auf die Spur zu helfen.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Es ist ein Beweis für die wahre, für die richtig verstandene wahre Religion, wenn sie uns überall auf das Schöne zurückbringt.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Für wohlgerathene Kinder können Eltern nicht zu viel thun. Aber wenn sich ein blöder Vater für einen ausgearteten Sohn das Blut vom Herzen zapft, dann wird Liebe zur Thorheit.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Reiz ist Schönheit in Bewegung.", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Töne, frohe Leier, // Töne Lust und Wein! // Töne, sanfte Leier, // Töne Liebe drein!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was ist ein Held ohne Menschenliebe?", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Welche Freude, wenn es heißt: Alter, du bist alt an Haaren, blühend aber ist dein Geist!", Author = "Gotthold Ephraim Lessing" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Gotthold_Ephraim_Lessing", Text = "Was ihn bewegt, bewegt; was ihm gefällt, gefällt. // Sein glücklicher Geschmack ist der Geschmack der Welt.", Author = "Gotthold Ephraim Lessing" },
